SELECT 1, 1, 549.00, 'PAGO', NULL, TIMESTAMP(DATE_ADD(@ini_A, INTERVAL k MONTH), '10:15:00'), TIMESTAMP(DATE_ADD(@ini_A, INTERVAL k MONTH), '08:00:00'), NULL, NULL, 'MANUAL', NULL
FROM (SELECT 0 AS k UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7) meses
WHERE DATE_ADD(@ini_A, INTERVAL k MONTH) <= @hoje ORDER BY k;
SELECT 2, 2, 279.00, 'PAGO', NULL, TIMESTAMP(DATE_ADD(@ini_B, INTERVAL k MONTH), '10:15:00'), TIMESTAMP(DATE_ADD(@ini_B, INTERVAL k MONTH), '08:00:00'), NULL, NULL, 'MANUAL', NULL
